import{_ as t,o as l,c as n,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const r="/bilder/unterricht-kataloge/kataloge-haltestelle.png",p=JSON.parse('{"title":"Haltestellen für den Schulweg verwalten","description":"","frontmatter":{"title":"Haltestellen für den Schulweg verwalten","source_pageid":336,"source_revision":4422},"headers":[],"relativePath":"schild3/unterricht-kataloge/haltestellen-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/haltestellen-allgemeine-kataloge.md"}'),i={name:"schild3/unterricht-kataloge/haltestellen-allgemeine-kataloge.md"};function s(o,e,d,h,c,g){return l(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="haltestellen-fur-den-schulweg-verwalten" tabindex="-1">Haltestellen für den Schulweg verwalten <a class="header-anchor" href="#haltestellen-fur-den-schulweg-verwalten" aria-label="Permalink to &quot;Haltestellen für den Schulweg verwalten&quot;">​</a></h1><p>Bereiten Sie die benötigten Haltestellen vor, damit sie in Individualdaten I ausgewählt werden können. Der Katalog unterstützt auch Sortierung und Sichtbarkeit.</p><p><a href="/bilder/unterricht-kataloge/kataloge-haltestelle.png"><img src="'+r+'" alt="Der Karteireiter Kataloge ➜ Haltestelle" loading="lazy"></a></p><p><em>Der Karteireiter Kataloge ➜ Haltestelle</em></p><p>Der Katalog der Haltestellen ist bei der Grundinstallation leer.</p><p>Dieser Katalog wird von Schulen verwendet, wenn Schulbusse oder andere Transportmittel verwendet werden und z.B. nachgehalten werden muss, wo die Schüler abgeholt werden sollen.</p><p>Um diese Information zu den Schülern mit Hilfe von SchILD-NRW abzubilden, müssen alle, bei Ihren Schülern vorkommenden Haltestellen im Katalog zuerst eingegeben werden.</p><p>Anschließend kann unter <em>Schüler ➜ Individual-Daten I ➜ Haltestelle</em> auf die einzelnen Möglichkeiten zugegriffen werden.</p><p>Durch das Plus <strong>+</strong> ist auch an dieser Stelle ein Eingeben von neuen Haltestellen möglich. Dies funktioniert zusätzlich zu der Möglichkeit über den Katalog.</p><p>Neben den üblichen Sortiermöglichkeiten kann hier auch nach der Entfernung sortiert werden. Darüber hinaus kann auch die Sichtbarkeit an- und ausgeschaltet werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Haltestellen_(Allgemeine_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4422.</p>',12)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
